var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if(scene.name!="BlackHoleStationSereneV013" || UnityEditor.EditorApplication.isPlaying || scene.isDirty)throw new System.Exception("Clean v013 required");
var probe=UnityEngine.GameObject.Find("Cafe local reflections").GetComponent<UnityEngine.ReflectionProbe>();
var before=new{mode=probe.mode.ToString(),texture=probe.texture?probe.texture.name:null,realtimeEnabled=UnityEngine.QualitySettings.realtimeReflectionProbes};
var folder="Assets/Station/Textures/SereneReflectionsV013";
if(!UnityEditor.AssetDatabase.IsValidFolder(folder))UnityEditor.AssetDatabase.CreateFolder("Assets/Station/Textures","SereneReflectionsV013");
var path=folder+"/CafeInterior.exr";
UnityEditor.Undo.RecordObject(probe,"Bake v013 cafe reflections");
probe.mode=UnityEngine.Rendering.ReflectionProbeMode.Custom;
probe.renderDynamicObjects=true;
probe.resolution=256;
if(!UnityEditor.Lightmapping.BakeReflectionProbe(probe,path))throw new System.Exception("Reflection bake failed");
UnityEditor.AssetDatabase.ImportAsset(path,UnityEditor.ImportAssetOptions.ForceSynchronousImport);
var cube=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Cubemap>(path);
if(!cube || cube.width!=256)throw new System.Exception("Baked reflection cubemap missing");
probe.customBakedTexture=cube;
UnityEditor.EditorUtility.SetDirty(probe);
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
UnityEditor.AssetDatabase.SaveAssets();
return new{before,mode=probe.mode.ToString(),texture=probe.texture.name,resolution=probe.texture.width,path,realtimeEnabled=UnityEngine.QualitySettings.realtimeReflectionProbes};
